def f(g):
    g=[row[:] for row in g]; H=len(g);W=len(g[0])
    out=[row[:] for row in g]
    # find closed rectangles of zeros whose interior is entirely non-zero
    import itertools
    for r1 in range(H):
        for c1 in range(W):
            if out[r1][c1]==0:
                for h in range(2,6):
                    if r1+h> H: break
                    if any(x!=0 for x in out[r1][c1:c1+h+1]): continue
                    for w in range(2,6):
                        if c1+w>W: break
                        if any(out[r1+h][c1:c1+w]==[0]*w): continue
                        # check top/bottom rows of rect are all zero across width w, side columns zero for all h
                        if all(out[r1][c1+c]==0 for c in range(w)) and all(out[r1+h][c1+c]==0 for c in range(w)):
                            if all(out[r1+dr][c1]==0 for dr in range(h+1)) and all(out[r1+dr][c1+w-1]==0 for dr in range(h+1)):
                                # interior strictly inside fully non-zero
                                inter=[(r,c) for r in range(r1+1,r1+h) for c in range(c1+1,c1+w)]
                                if all(out[r][c]!=0 for r,c in inter):
                                    for r,c in inter: out[r][c]=0
    return out
